spec.query:
1 - (
  (
    # Running workload (0 for AZs with none)
    (
      sum by (availability_zone, region) (
        max by (compute_host, resource, availability_zone, region) (
          cortex_vmware_host_capacity_usage{
            resource="ram",
            workload_type="general-purpose",
            decommissioned="false",
            external_customer="false",
            pinned_projects="false"
          }
        )
      )
      or
      (0 * sum by (availability_zone, region) (
        max by (compute_host, resource, availability_zone, region) (
          cortex_vmware_host_capacity_total{
            resource="ram",
            workload_type="general-purpose",
            decommissioned="false",
            external_customer="false",
            pinned_projects="false"
          }
        )
      ))
    )

    +

    # Decommissioned workload (0 for AZs with none)
    (
      sum by (availability_zone, region) (
        max by (compute_host, resource, availability_zone, region) (
          cortex_vmware_host_capacity_usage{
            resource="ram",
            workload_type="general-purpose",
            decommissioned="true",
            external_customer="false",
            pinned_projects="false"
          }
        )
      )
      or
      (0 * sum by (availability_zone, region) (
        max by (compute_host, resource, availability_zone, region) (
          cortex_vmware_host_capacity_total{
            resource="ram",
            workload_type="general-purpose",
            decommissioned="false",
            external_customer="false",
            pinned_projects="false"
          }
        )
      ))
    )

    +

    # Unused commitments (0 for AZs with none)
    (
      sum by (availability_zone, region) (
        max by (availability_zone, project_id, resource, region) (
          cortex_vmware_unused_commitments_general_purpose{
            resource="ram"
          }
        )
      )
      or
      (0 * sum by (availability_zone, region) (
        max by (compute_host, resource, availability_zone, region) (
          cortex_vmware_host_capacity_total{
            resource="ram",
            workload_type="general-purpose",
            decommissioned="false",
            external_customer="false",
            pinned_projects="false"
          }
        )
      ))
    )
  )

  /

  # Total available RAM
  sum by (availability_zone, region) (
    max by (compute_host, resource, availability_zone, region) (
      cortex_vmware_host_capacity_total{
        resource="ram",
        workload_type="general-purpose",
        decommissioned="false",
        external_customer="false",
        pinned_projects="false"
      }
    )
  )
)

